<script setup lang="ts">
import { computed, inject, nextTick, onBeforeUnmount, onMounted, ref, watch, type ComputedRef } from 'vue';
import { Check, Layers3, LoaderCircle, Search, ShieldCheck, X } from 'lucide-vue-next';
import type { LabelColumn, LabelTemplate, RepositoryPermissions } from '@oxen/shared';
import { request } from '../api';
const props=defineProps<{columns:LabelColumn[];busy:boolean;error?:string}>();
const permissions=inject<ComputedRef<RepositoryPermissions>>('repositoryPermissions');
const canManageSchema=computed(()=>permissions?.value.capabilities?.['schema.manage']===true);
const emit=defineEmits<{close:[];apply:[template:LabelTemplate,keys:string[]]}>();
const templates=ref<LabelTemplate[]>([]),selectedId=ref(''),selectedKeys=ref<string[]>([]),loading=ref(true),loadError=ref(''),search=ref('');
let mounted=true;
const dialogRoot=ref<HTMLElement|null>(null),searchInput=ref<HTMLInputElement|null>(null);
let previousFocus:HTMLElement|null=null;
function trapFocus(event:KeyboardEvent){const controls=Array.from(dialogRoot.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),[href],select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')??[]).filter(item=>item.getClientRects().length>0);const first=controls[0],last=controls.at(-1);if(!first){event.preventDefault();dialogRoot.value?.focus();return;}if(event.shiftKey&&(document.activeElement===first||!dialogRoot.value?.contains(document.activeElement))){event.preventDefault();last?.focus();}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===dialogRoot.value)){event.preventDefault();first.focus();}}
const selected=computed(()=>templates.value.find(item=>item.id===selectedId.value));
const filtered=computed(()=>templates.value.filter(item=>(item.name+' '+item.description).toLowerCase().includes(search.value.toLowerCase())));
const existing=computed(()=>new Set(props.columns.map(column=>column.semanticKey).filter(Boolean)));
const newCount=computed(()=>selectedKeys.value.filter(key=>!existing.value.has(key)).length);
const scopeName=(scope:string)=>({dataset:'数据集',file:'文件',row:'条目'}[scope]??scope);
function choose(template:LabelTemplate){selectedId.value=template.id;selectedKeys.value=template.columns.map(column=>column.semanticKey);}
function chooseMobile(event:Event){const template=templates.value.find(item=>item.id===(event.target as HTMLSelectElement).value);if(template)choose(template);}
function toggle(key:string){selectedKeys.value=selectedKeys.value.includes(key)?selectedKeys.value.filter(value=>value!==key):[...selectedKeys.value,key];}
async function load(){if(!canManageSchema.value){loading.value=false;loadError.value='当前身份不能维护规范，请在项目中使用已发布模板。';return;}loading.value=true;loadError.value='';try{const value=await request<LabelTemplate[]>('/label-templates');if(!mounted||!canManageSchema.value)return;templates.value=value;if(value[0])choose(value[0]);}catch(cause){if(mounted)loadError.value=(cause as Error).message;}finally{if(mounted)loading.value=false;}}
watch(canManageSchema,allowed=>{if(!allowed){templates.value=[];selectedKeys.value=[];selectedId.value='';loadError.value='当前身份不能维护规范。';}});
onMounted(async()=>{previousFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;dialogRoot.value?.focus();await load();await nextTick();if(mounted)searchInput.value?.focus();});onBeforeUnmount(()=>{mounted=false;if(previousFocus&&document.contains(previousFocus))previousFocus.focus();});
</script>
<template>
  <Teleport to="body">
  <div class="modal-backdrop template-backdrop" @click.self="!busy&&emit('close')" @keydown.esc.stop="!busy&&emit('close')">
    <section ref="dialogRoot" class="template-dialog" role="dialog" aria-modal="true" aria-labelledby="template-title" tabindex="-1" @keydown.tab="trapFocus">
      <header><div><span class="template-eyebrow"><Layers3 :size="15"/>标注配置</span><h2 id="template-title">选择标签模板</h2><p>从通用模板开始，或选用 AI 安全领域模板。应用后可以继续自定义。</p></div><button class="icon-button" :disabled="busy" aria-label="关闭标签模板" @click="emit('close')"><X :size="20"/></button></header>
      <div v-if="loading" class="empty" role="status"><LoaderCircle class="spin" :size="24"/>正在加载预制模板…</div>
      <div v-else-if="loadError" class="error-state" role="alert">{{loadError}}<button class="btn" @click="load">重试</button></div>
      <div v-else class="template-layout">
        <label class="template-mobile-picker">预制模板<select aria-label="预制标签模板" :value="selectedId" :disabled="busy" @change="chooseMobile"><option v-for="item in templates" :key="item.id" :value="item.id">{{item.name}} · {{item.columns.length}} 维度</option></select></label>
        <aside class="template-catalog"><label class="search-field"><Search :size="15"/><input ref="searchInput" v-model="search" aria-label="搜索标签模板" placeholder="搜索领域或模板…" :disabled="busy"/></label><button v-for="item in filtered" :key="item.id" class="template-card" :class="{selected:selectedId===item.id}" :disabled="busy" @click="choose(item)"><span><ShieldCheck v-if="item.category!=='general'" :size="18"/><Layers3 v-else :size="18"/><strong>{{item.name}}</strong><Check v-if="selectedId===item.id" :size="16"/></span><p>{{item.description}}</p><small>{{item.columns.length}} 个标签维度 · v{{item.version}}</small></button><p v-if="!filtered.length" class="empty">没有匹配的模板</p></aside>
        <section v-if="selected" class="template-preview" :aria-label="selected.name+'字段预览'"><div class="template-preview-heading"><div><h3>{{selected.name}}</h3><p>选择需要的维度。已有同语义字段会复用并保留你的自定义。</p></div><button class="btn btn-ghost" :disabled="busy" @click="selectedKeys=selectedKeys.length===selected.columns.length?[]:selected.columns.map(column=>column.semanticKey)">{{selectedKeys.length===selected.columns.length?'取消全选':'全选'}}</button></div><label v-for="column in selected.columns" :key="column.semanticKey" class="template-field"><input type="checkbox" :checked="selectedKeys.includes(column.semanticKey)" :disabled="busy" @change="toggle(column.semanticKey)"/><span><span class="template-field-name"><strong>{{column.name}}</strong><i>{{column.type==='single'?'单选':column.type==='multi'?'多选':'文本'}}</i><i v-if="existing.has(column.semanticKey)" class="existing-field">已配置</i></span><small>{{column.description}}</small><span class="template-options" v-if="column.options?.length">{{column.options.map(option=>option.value).join(' / ')}}</span><span class="template-scopes">{{column.scopes?.map(scopeName).join(' · ')||'所有层级'}}</span></span></label></section>
      </div>
      <footer><div><strong>已选 {{selectedKeys.length}} 个维度，新增 {{newCount}} 列</strong><p>一次版本提交保存配置；不覆盖原始样本、已有标签或人工结论。</p><p v-if="error" class="form-error" role="alert">{{error}}</p></div><div><button class="btn" :disabled="busy" @click="emit('close')">取消</button><button class="btn btn-primary" :disabled="busy||loading||!selected||!selectedKeys.length" @click="selected&&emit('apply',selected,[...selectedKeys])"><LoaderCircle v-if="busy" class="spin" :size="16"/><Check v-else :size="16"/>{{busy?'正在保存配置…':'应用模板并提交'}}</button></div></footer>
    </section>
  </div>
  </Teleport>
</template>
<style scoped>
.template-backdrop{z-index:110}.template-dialog{width:1120px;max-width:100%;max-height:calc(100vh - 48px);display:flex;flex-direction:column;border:1px solid var(--line);border-radius:10px;background:var(--surface);box-shadow:0 25px 100px #0008;overflow:hidden}.template-dialog>header{display:flex;justify-content:space-between;align-items:start;gap:20px;padding:24px 26px;border-bottom:1px solid var(--line)}.template-eyebrow{display:flex;align-items:center;gap:8px;color:var(--accent);font-size:12px;margin-bottom:8px}.template-dialog h2{font-size:23px}.template-dialog>header p{font-size:13px;color:var(--muted);margin-top:8px}.template-layout{display:grid;grid-template-columns:290px minmax(0,1fr);min-height:0;flex:1;overflow:hidden}.template-catalog{padding:18px;border-right:1px solid var(--line);overflow:auto;background:var(--bg)}.template-catalog>.search-field{margin-bottom:14px}.template-card{display:block;text-align:left;width:100%;border:1px solid var(--line);border-radius:6px;background:var(--surface);padding:15px;margin:0 0 10px}.template-card:hover,.template-card.selected{border-color:var(--primary);background:var(--primary-soft)}.template-card>span{display:flex;align-items:center;gap:8px}.template-card strong{flex:1;font-size:14px}.template-card>span>svg{color:var(--accent)}.template-card p{font-size:12px;color:var(--muted);line-height:1.7;margin:10px 0}.template-card small{font-size:11px;color:var(--muted)}.template-preview{min-width:0;overflow:auto;padding:20px 24px}.template-preview-heading{display:flex;align-items:start;gap:18px;justify-content:space-between;margin-bottom:17px}.template-preview-heading h3{font-size:17px}.template-preview-heading p{font-size:12px;color:var(--muted);line-height:1.7;margin-top:7px}.template-preview-heading .btn{white-space:nowrap;font-size:12px}.template-field{display:flex;align-items:start;gap:12px;padding:15px 0;border-top:1px solid var(--line);cursor:pointer}.template-field>input{margin-top:4px;flex-shrink:0}.template-field>span{min-width:0;flex:1}.template-field-name{display:flex;gap:8px;align-items:center}.template-field-name strong{font-size:13px}.template-field-name i{font-style:normal;font-size:10px;color:var(--muted);padding:1px 6px;border:1px solid var(--line);border-radius:4px}.template-field-name .existing-field{color:var(--success)}.template-field small{display:block;color:var(--muted);font-size:12px;line-height:1.7;margin-top:6px}.template-options{display:block;font-size:11px;line-height:1.8;color:var(--muted);margin-top:6px}.template-scopes{display:block;color:var(--accent);font-size:10px;margin-top:7px}.template-dialog>footer{display:flex;align-items:center;gap:20px;justify-content:space-between;border-top:1px solid var(--line);padding:18px 26px;background:var(--surface-raised)}.template-dialog>footer strong{font-size:13px}.template-dialog>footer p{font-size:12px;color:var(--muted);margin-top:6px}.template-dialog>footer>div:last-child{display:flex;gap:10px;flex-shrink:0}.template-dialog>footer .form-error{color:var(--danger)}
@media(max-width:760px){.template-dialog{max-height:calc(100vh - 28px)}.template-dialog>header{padding:18px}.template-dialog h2{font-size:20px}.template-layout{grid-template-columns:1fr;overflow:auto}.template-catalog{border-right:0;border-bottom:1px solid var(--line);max-height:230px;overflow:auto;padding:14px}.template-card{padding:12px}.template-card p{margin:5px 0}.template-preview{overflow:visible;padding:18px}.template-dialog>footer{padding:15px;flex-wrap:wrap;gap:12px}.template-dialog>footer>div:last-child{width:100%;justify-content:end}}
</style>

<style scoped>.template-catalog{min-width:0}.template-catalog>.search-field{min-width:0;width:100%}.template-card>span,.template-card strong{min-width:0;overflow-wrap:anywhere}</style>

<style scoped>.template-mobile-picker{display:none}.template-dialog>header,.template-dialog>footer{flex-shrink:0}@media(max-width:760px){.template-layout{display:block;overflow:auto}.template-catalog{display:none}.template-mobile-picker{display:block;padding:15px 18px;border-bottom:1px solid var(--line);font-size:12px;color:var(--muted)}.template-mobile-picker select{display:block;width:100%;margin-top:8px;min-width:0;padding:9px;background:var(--surface-raised);border:1px solid var(--line);border-radius:5px;color:var(--text)}.template-preview{overflow:visible}}</style>
